//Decided to split the screen in half, and I discovered endless possibilities.
//Emabarked on animation using trig functions with iTime

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec3 color = vec3(0.);
    vec2 uv = ( fragCoord -.5* iResolution.xy ) / iResolution.y; // Normalization

    //Parameters we can play with to create fun animations
    float ew = .005;                // sharper edges parameter 
    float wh = sin(iTime)*.2 ;      // wave hight parameter (amplitude), zoom effect
    float wl = cos(iTime)*20.;      // wave Length parameter (period)

    //Splitting + smoothing edges
    color += smoothstep(
        sin(uv.y * wl) * wh - ew,
        sin(uv.y * wl) * wh + ew,  // to split horizontally just move all uv.x -> uv.y 
        uv.x                       // and viceversa
    );

    // Output to screen
    fragColor = vec4(mix(color, vec3(.5, .2, .5), .8), 1.);
}

